def limiter_storage_status():
    """Limiter depolama durumunu döndür: "memory" (Redis yapılandırılmamış —
    lokal/dev), "redis" (yapılandırılmış ve erişilebilir) veya "degraded"
    (yapılandırılmış ama PING başarısız → bellek-yedeğine düşülmüş).

    "degraded" güvenlik açısından önemlidir: rate-limit ve özellikle kullanıcı-
    başı login throttle (brute-force koruması) o anda süreç-yerel + geçici (yeniden
    başlatmada sıfırlanır) ve birden çok worker'a yayılmaz. /health bu değeri
    raporlar ki harici izleme sessiz bozulmayı yakalayabilsin (S6)."""
    if redis_client is None:
        return "memory"
    try:
        redis_client.ping()
        return "redis"
    except Exception:
        return "degraded"


def warn_if_limiter_degraded(app):
    """Redis yapılandırılmış ama erişilemiyorsa boot'ta görünür şekilde uyar.
    Limiter bu durumda bellek yedeğine düşer (in_memory_fallback_enabled).
    Çalışma anındaki durum /health üzerinden de izlenebilir (limiter_storage_status)."""
    if limiter_storage_status() == "degraded":
        app.logger.error(
            "[LIMITER] Redis erişilemiyor — rate-limit ve login throttle "
            "bellek-yedeğine düştü; çok-süreçli/yeniden-başlatmada zayıflar. "
            "/health limiter_storage=degraded raporlar.")


# Login throttle sağlık durumu, kısa süreli cache'lenir: Redis düştüğünde her
# login isteğinin ping için socket_connect_timeout kadar bloklanmasını (ve yavaş
# 503 üretmesini) engeller. checked_at=0 → testler yeniden kontrolü zorlayabilir.
_LOGIN_THROTTLE_HEALTH = {"ok": True, "checked_at": 0.0}
_LOGIN_THROTTLE_TTL = 5.0  # saniye


def login_throttle_available():
    """Login brute-force throttle'ı güvenilir biçimde uygulanabiliyor mu?

    - Redis YAPILANDIRILMAMIŞSA (memory:// kasıtlı store) → True; tek-süreç
      throttle tasarımın parçası, login normal çalışır.
    - Redis YAPILANDIRILMIŞ ama erişilemiyorsa → False; limiter bellek-yedeğine
      düşmüş, dağıtık throttle zayıflamıştır. Çağıran (login) bu durumda
      fail-closed davranıp 503 dönebilir.
    """
    if redis_client is None:
        return True
    now = time.monotonic()
    if now - _LOGIN_THROTTLE_HEALTH["checked_at"] < _LOGIN_THROTTLE_TTL:
        return _LOGIN_THROTTLE_HEALTH["ok"]
    try:
        redis_client.ping()
        _LOGIN_THROTTLE_HEALTH["ok"] = True
    except Exception:
        _LOGIN_THROTTLE_HEALTH["ok"] = False
    _LOGIN_THROTTLE_HEALTH["checked_at"] = now
    return _LOGIN_THROTTLE_HEALTH["ok"]


def _user_or_ip_key():
    """Rate-limit key: the user id when logged in, else the client IP. The AI
    routes are all @login_required, so in practice each account gets its own
    budget regardless of source IP."""
    try:
        if current_user.is_authenticated:
            return f"user:{current_user.id}"
    except Exception:
        pass
    return get_remote_address()
